import * as vscode from "vscode";
import type { SendExtras } from "./ChatViewProvider";
import type { ToolResult } from "./DiagramToolbox";
import { sanitizeImages } from "./images";
import type { ImageData } from "./providers/types";
import { describeContext, SelectionContext } from "./systemPrompt";

/** The custom agent contributed in media/chat/draw-ai.agent.md (generated by scripts/sync-lm-tools.js). */
export const NATIVE_AGENT = "Draw.AI";

/**
 * Oldest VS Code verified to load extension-contributed agents and to open its
 * chat on one by name. Older versions would silently use the current chat mode.
 */
export const MIN_NATIVE_VSCODE = "1.142.0";

export type ChatSurface = "auto" | "native" | "panel";

const ATTACHMENTS_DIR = "chat-attachments";
/** Long enough to rerun or continue a chat the next days. */
const ATTACHMENT_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const IMAGE_EXT: Record<ImageData["mimeType"], string> = {
	"image/png": "png",
	"image/jpeg": "jpg",
	"image/gif": "gif",
	"image/webp": "webp",
};

export function configuredSurface(): ChatSurface {
	const value = vscode.workspace.getConfiguration("drawio-ai").get("chatSurface");
	return value === "native" || value === "panel" ? value : "auto";
}

function versionAtLeast(version: string, min: string): boolean {
	const a = version.split(/[.-]/).map((n) => parseInt(n, 10) || 0);
	const b = min.split(".").map((n) => parseInt(n, 10) || 0);
	for (let i = 0; i < 3; i++) {
		if (a[i] !== b[i]) return a[i] > b[i];
	}
	return true;
}

/**
 * Whether VS Code's chat can run the Draw.AI agent: agent mode and AI features
 * are on, VS Code is recent enough, and some extension provides a chat model.
 */
export async function nativeChatAvailable(): Promise<boolean> {
	const chat = vscode.workspace.getConfiguration("chat");
	if (chat.get("agent.enabled") === false || chat.get("disableAIFeatures") === true) {
		return false;
	}
	if (!versionAtLeast(vscode.version, MIN_NATIVE_VSCODE)) {
		return false;
	}
	try {
		return (await vscode.lm.selectChatModels()).length > 0;
	} catch {
		return false;
	}
}

/** Opens VS Code's chat on the Draw.AI agent. */
export async function openNativeChat(): Promise<void> {
	await vscode.commands.executeCommand("workbench.action.chat.open", { mode: NATIVE_AGENT });
}

/**
 * Sends a request from the diagram to VS Code's chat, on the Draw.AI agent. The
 * selection (or lasso, markup, image) is described at the end of the message, the
 * same context the Draw.AI panel gives its model. Images and long inputs (a code
 * analysis) are stored and named in the message; the agent reads them with
 * drawio_get_attachment. (Chat file attachments are not used: VS Code attaches
 * images after sending, and not at all on the web.)
 */
export async function sendToNativeChat(
	storage: vscode.Uri,
	text: string,
	selection: SelectionContext | undefined,
	extras: SendExtras
): Promise<{ query: string }> {
	const editor = extras.editor;
	const fileName = editor?.uri.path.split("/").pop();
	const parts = [
		text.trim(),
		"---",
		describeContext(fileName, selection ?? { cellIds: [...(editor?.drawioClient.currentSelection ?? [])] }),
	];
	const attachments = await storeAttachments(storage, extras);
	if (attachments.length) {
		parts.push(
			`Attached (read each with drawio_get_attachment before you start): ${attachments
				.map((a) => `"${a.id}" (${a.description})`)
				.join(", ")}.`
		);
	}
	const query = parts.join("\n");
	await vscode.commands.executeCommand("workbench.action.chat.open", {
		mode: NATIVE_AGENT,
		query,
		isPartialQuery: false,
	});
	return { query };
}

async function storeAttachments(storage: vscode.Uri, extras: SendExtras): Promise<{ id: string; description: string }[]> {
	const items: { file: string; description: string; data: Uint8Array }[] = [];
	sanitizeImages(extras.images).forEach((image, i) => {
		items.push({
			file: `${items.length + 1}.${IMAGE_EXT[image.mimeType]}`,
			description: `image ${i + 1}`,
			data: Uint8Array.from(atob(image.base64), (c) => c.charCodeAt(0)),
		});
	});
	for (const a of extras.attachments ?? []) {
		items.push({ file: `${items.length + 1}.md`, description: a.name, data: new TextEncoder().encode(a.text) });
	}
	if (items.length === 0) {
		return [];
	}
	// One folder per request, so attachments of different requests never collide.
	const folder = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
	const dir = vscode.Uri.joinPath(storage, ATTACHMENTS_DIR, folder);
	await vscode.workspace.fs.createDirectory(dir);
	for (const item of items) {
		await vscode.workspace.fs.writeFile(vscode.Uri.joinPath(dir, item.file), item.data);
	}
	return items.map((item) => ({ id: `${folder}/${item.file}`, description: item.description }));
}

/** The drawio_get_attachment tool: returns an image or text stored for a request. */
export async function readAttachment(storage: vscode.Uri, id: string): Promise<ToolResult> {
	const m = /^(\d+-[a-z0-9]+)\/(\d+)\.(png|jpg|gif|webp|md)$/.exec(String(id ?? "").trim());
	if (!m) {
		return { isError: true, summary: "Unknown attachment", text: `"${id}" is not an attachment id from the request.` };
	}
	let data: Uint8Array;
	try {
		data = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(storage, ATTACHMENTS_DIR, m[1], `${m[2]}.${m[3]}`));
	} catch {
		return {
			isError: true,
			summary: "Attachment expired",
			text: "This attachment no longer exists (attachments are kept for 7 days). Ask the user to send the request again.",
		};
	}
	if (m[3] === "md") {
		return { text: new TextDecoder().decode(data), summary: "Read attached text" };
	}
	const mimeType = (Object.keys(IMAGE_EXT) as ImageData["mimeType"][]).find((k) => IMAGE_EXT[k] === m[3])!;
	let binary = "";
	for (let i = 0; i < data.length; i += 0x8000) {
		binary += String.fromCharCode.apply(null, Array.from(data.subarray(i, i + 0x8000)));
	}
	return {
		text: "The attached image is included.",
		image: { mimeType, base64: btoa(binary) },
		summary: "Read attached image",
	};
}

/** Deletes request attachments older than a week. */
export async function pruneAttachments(storage: vscode.Uri, now = Date.now()): Promise<void> {
	const dir = vscode.Uri.joinPath(storage, ATTACHMENTS_DIR);
	let entries: [string, vscode.FileType][];
	try {
		entries = await vscode.workspace.fs.readDirectory(dir);
	} catch {
		return;
	}
	for (const [name] of entries) {
		const stamp = parseInt(name, 10);
		if (Number.isFinite(stamp) && now - stamp > ATTACHMENT_TTL_MS) {
			await vscode.workspace.fs.delete(vscode.Uri.joinPath(dir, name), { recursive: true }).then(undefined, () => undefined);
		}
	}
}
